class ShopApp extends StatelessWidget {const ShopApp({super.key}); @override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Ruang Belanja',theme:ThemeData(useMaterial3:true,scaffoldBackgroundColor:canvas,colorScheme:ColorScheme.fromSeed(seedColor:accent),fontFamily:'Roboto',appBarTheme:const AppBarTheme(backgroundColor:canvas,foregroundColor:ink,elevation:0)),home:const HomeScreen());}

class HomeScreen extends ConsumerStatefulWidget {const HomeScreen({super.key}); @override ConsumerState<HomeScreen> createState()=>_HomeState();}
