class CartScreen extends ConsumerWidget {const CartScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final cart=ref.watch(cartProvider);final items=demoProducts.where((p)=>cart.containsKey(p.id)).toList();final total=items.fold<int>(0,(s,p)=>s+p.price*cart[p.id]!);return Scaffold(appBar:AppBar(title:const Text('Keranjang',style:TextStyle(fontSize:17,fontWeight:FontWeight.w700)),leading:IconButton(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.arrow_back))),body:items.isEmpty?const Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.shopping_bag_outlined,size:55,color:muted),SizedBox(height:12),Text('Keranjangmu masih kosong',style:TextStyle(fontWeight:FontWeight.w600)),SizedBox(height:4),Text('Yuk temukan sesuatu yang kamu suka.',style:TextStyle(color:muted))])):Column(children:[Expanded(child:ListView.separated(padding:const EdgeInsets.all(20),itemCount:items.length,separatorBuilder:(_,__)=>const Divider(height:26),itemBuilder:(c,i){final p=items[i];final q=cart[p.id]!;return Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Container(height:82,width:78,decoration:BoxDecoration(color:Color(p.color),borderRadius:BorderRadius.circular(14)),child:Center(child:Text(p.emoji,style:const TextStyle(fontSize:36)))),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(p.name,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:14,fontWeight:FontWeight.w600)),const SizedBox(height:7),Text(rupiah(p.price),style:const TextStyle(color:accent,fontWeight:FontWeight.w700)),const SizedBox(height:6),Row(children:[_qtyButton(Icons.remove,()=>ref.read(cartProvider.notifier).setQty(p.id,q-1)),Padding(padding:const EdgeInsets.symmetric(horizontal:12),child:Text('$q',style:const TextStyle(fontWeight:FontWeight.w600))),_qtyButton(Icons.add,()=>ref.read(cartProvider.notifier).add(p)),const Spacer(),IconButton(onPressed:()=>ref.read(cartProvider.notifier).remove(p.id),icon:const Icon(Icons.delete_outline,color:muted,size:21),visualDensity:VisualDensity.compact)])]))]);})),Container(padding:const EdgeInsets.fromLTRB(22,18,22,25),decoration:const BoxDecoration(color:Colors.white,borderRadius:BorderRadius.vertical(top:Radius.circular(22))),child:Column(children:[Row(children:[const Text('Total belanja',style:TextStyle(color:muted)),const Spacer(),Text(rupiah(total),style:const TextStyle(fontWeight:FontWeight.w700,fontSize:18))]),const SizedBox(height:15),SizedBox(width:double.infinity,child:FilledButton(style:FilledButton.styleFrom(backgroundColor:accent,padding:const EdgeInsets.symmetric(vertical:16),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(13))),onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>CheckoutScreen(total:total))),child:const Text('Lanjut checkout simulasi')))]))]));}}
