class CheckoutScreen extends ConsumerWidget {const CheckoutScreen({super.key,required this.total});final int total;@override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Checkout simulasi',style:TextStyle(fontSize:17,fontWeight:FontWeight.w700))),body:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Container(width:double.infinity,padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:const Color(0xffe5f0e9),borderRadius:BorderRadius.circular(18)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.check_circle_outline,color:accent,size:30),SizedBox(height:12),Text('Hampir selesai!',style:TextStyle(fontSize:21,fontWeight:FontWeight.w700)),SizedBox(height:6),Text('Ini hanya simulasi untuk prototipe. Tidak ada pembayaran atau pengiriman nyata.',style:TextStyle(height:1.45,color:muted))])),const SizedBox(height:25),const Text('Ringkasan pesanan',style:TextStyle(fontSize:16,fontWeight:FontWeight.w700)),const SizedBox(height:14),_summary('Subtotal',rupiah(total)),const SizedBox(height:10),_summary('Biaya lain','Rp 0'),const Divider(height:28),_summary('Total',rupiah(total),bold:true),const Spacer(),SizedBox(width:double.infinity,child:FilledButton(style:FilledButton.styleFrom(backgroundColor:accent,padding:const EdgeInsets.symmetric(vertical:16),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(13))),onPressed:(){ref.read(cartProvider.notifier).clear();showDialog(context:context,builder:(d)=>AlertDialog(icon:const Icon(Icons.check_circle,color:accent,size:42),title:const Text('Pesanan simulasi berhasil'),content:const Text('Terima kasih sudah mencoba prototipe Ruang.'),actions:[TextButton(onPressed:(){Navigator.pop(d);Navigator.popUntil(context,(r)=>r.isFirst);},child:const Text('Selesai'))]));},child:const Text('Konfirmasi pesanan simulasi')))])));}
Widget _summary(String a,String b,{bool bold=false})=>Row(children:[Text(a,style:TextStyle(color:bold?ink:muted,fontWeight:bold?FontWeight.w700:null)),const Spacer(),Text(b,style:TextStyle(fontWeight:bold?FontWeight.w700:null,fontSize:bold?17:14))]);

